# Validation regression tests for ClinicoPath::hullplot
# Generated by /validate-function hullplot depth=exhaustive (2026-11-20)
# Covers verified claims (live tests) and confirmed open defects (skip-guarded).

library(testthat)

val_strip_html <- function(x) {
    x <- gsub("<[^>]+>", " ", x)
    x <- gsub("&lt;", "<", x, fixed = TRUE)
    x <- gsub("&gt;", ">", x, fixed = TRUE)
    x <- gsub("&amp;", "&", x, fixed = TRUE)
    trimws(gsub("\\s+", " ", x))
}

# --- Live tests for verified claims ---

test_that("C01/C02/C03/C04/C05/C07: hand-calculated tiny dataset matches exact arithmetic", {
    # Oracle: hand arithmetic (Ctrl: x=c(0,1,2,2,10), y=c(0,1,2,3,6); Case: x=c(20,21,22,22,23,24), y=c(10..14); 1 NA)
    d <- data.frame(
        x = c(0, 1, 2, 2, 10, NA, 20, 21, 22, 22, 23, 24),
        y = c(0, 1, 2, 3,  6,  5, 10, 11, 12, 12, 13, 14),
        g = factor(c(rep("Ctrl", 6), rep("Case", 6)), levels = c("Ctrl", "Case"))
    )
    res <- suppressWarnings(ClinicoPath::hullplot(
        data = d, x_var = "x", y_var = "y", group_var = "g",
        show_statistics = TRUE, outlier_detection = TRUE, show_summary = TRUE
    ))
    st <- res$statistics$asDF
    expect_equal(st$group, c("Ctrl", "Case"))
    expect_equal(st$n, c(5L, 6L))
    expect_equal(st$x_mean, c(3.00, 22.00), tolerance = 1e-8)
    expect_equal(st$x_sd, c(4.00, sqrt(2)), tolerance = 1e-8)
    expect_equal(st$y_mean, c(2.40, 12.00), tolerance = 1e-8)
    expect_equal(st$y_sd, c(sqrt(5.3), sqrt(2)), tolerance = 1e-8)

    out_txt <- val_strip_html(res$outliers$content)
    expect_match(out_txt, "Ctrl: 1 potential outlier detected", fixed = TRUE)
    expect_match(out_txt, "Case: 0 potential outliers detected", fixed = TRUE)
    expect_match(out_txt, "Total potential outliers in assessed groups: 1", fixed = TRUE)

    sum_txt <- val_strip_html(res$summary$content)
    expect_match(sum_txt, "described as well-separated", fixed = TRUE)
    expect_match(sum_txt, "Ctrl: 5 observations (45.5% of total)", fixed = TRUE)
    expect_match(sum_txt, "Case: 6 observations (54.5% of total)", fixed = TRUE)

    not_txt <- val_strip_html(res$notices$content)
    expect_match(not_txt, "1 of 12 rows (8.3%)", fixed = TRUE)
    expect_match(not_txt, "11 rows were plotted", fixed = TRUE)
})

test_that("C01/C02/C03: reference parity on canonical datasets::iris", {
    # Oracle: base-R tapply + stats::quantile(..., type = 7) on datasets::iris
    res <- ClinicoPath::hullplot(
        data = datasets::iris, x_var = "Sepal.Length", y_var = "Petal.Length", group_var = "Species",
        show_statistics = TRUE, outlier_detection = TRUE, show_summary = TRUE
    )
    st <- res$statistics$asDF
    exp_n  <- as.integer(table(datasets::iris$Species))
    exp_xm <- as.numeric(tapply(datasets::iris$Sepal.Length, datasets::iris$Species, mean))
    exp_xs <- as.numeric(tapply(datasets::iris$Sepal.Length, datasets::iris$Species, sd))
    expect_equal(st$n, exp_n)
    expect_equal(st$x_mean, exp_xm, tolerance = 1e-8)
    expect_equal(st$x_sd, exp_xs, tolerance = 1e-8)
})

test_that("C02/C03/C04: metamorphic invariance under row permutation and positive affine rescaling", {
    # Oracle: metamorphic invariance properties (row permutation, affine scaling of X and Y)
    set.seed(20260101)
    res0 <- ClinicoPath::hullplot(
        data = datasets::iris, x_var = "Sepal.Length", y_var = "Petal.Length", group_var = "Species",
        show_statistics = TRUE, outlier_detection = TRUE, show_summary = TRUE
    )
    res_p <- ClinicoPath::hullplot(
        data = datasets::iris[sample(nrow(datasets::iris)), ],
        x_var = "Sepal.Length", y_var = "Petal.Length", group_var = "Species",
        show_statistics = TRUE, outlier_detection = TRUE, show_summary = TRUE
    )
    expect_equal(res_p$statistics$asDF, res0$statistics$asDF, tolerance = 1e-12)
    expect_identical(res_p$outliers$content, res0$outliers$content)
    expect_identical(res_p$summary$content, res0$summary$content)

    iris_sc <- datasets::iris
    iris_sc$Sepal.Length <- iris_sc$Sepal.Length * 1000 + 50
    iris_sc$Petal.Length <- iris_sc$Petal.Length * 0.01 - 20
    res_sc <- ClinicoPath::hullplot(
        data = iris_sc, x_var = "Sepal.Length", y_var = "Petal.Length", group_var = "Species",
        outlier_detection = TRUE, show_summary = TRUE
    )
    expect_identical(res_sc$outliers$content, res0$outliers$content)
    expect_match(val_strip_html(res_sc$summary$content), "described as well-separated", fixed = TRUE)
})

test_that("C04: exact threshold boundaries at discrim_index = 1.5 and 3.0", {
    # Oracle: exact analytical construction where discrim_index = dx / sqrt(2)
    make_d <- function(target_d) {
        dx <- target_d * sqrt(2)
        data.frame(x = c(-1, 1, -1 + dx, 1 + dx), y = c(-1, 1, -1, 1), g = factor(c("A", "A", "B", "B")))
    }
    expect_match(val_strip_html(ClinicoPath::hullplot(make_d(1.5), "x", "y", "g", show_summary = TRUE)$summary$content),
                 "described as overlapping", fixed = TRUE)
    expect_match(val_strip_html(ClinicoPath::hullplot(make_d(1.501), "x", "y", "g", show_summary = TRUE)$summary$content),
                 "described as moderately separated", fixed = TRUE)
    expect_match(val_strip_html(ClinicoPath::hullplot(make_d(3.0), "x", "y", "g", show_summary = TRUE)$summary$content),
                 "described as moderately separated", fixed = TRUE)
    expect_match(val_strip_html(ClinicoPath::hullplot(make_d(3.001), "x", "y", "g", show_summary = TRUE)$summary$content),
                 "described as well-separated", fixed = TRUE)
})

test_that("C08: guard thresholds fire at exact boundaries (n=2/3, 3/4, 4/5; k=10/11)", {
    # Oracle: documented thresholds in hullplot.a.yaml and R/hullplot.b.R
    set.seed(42)
    mk <- function(nA) data.frame(x = c(rnorm(nA), rnorm(10, 5)), y = c(rnorm(nA), rnorm(10, 5)),
                                  g = factor(c(rep("A", nA), rep("B", 10))))
    expect_match(val_strip_html(ClinicoPath::hullplot(mk(2), "x", "y", "g")$notices$content),
                 "Groups with fewer than 3 points", fixed = TRUE)
    expect_false(grepl("Groups with fewer than 3 points",
                       val_strip_html(ClinicoPath::hullplot(mk(3), "x", "y", "g")$notices$content), fixed = TRUE))
    expect_match(val_strip_html(ClinicoPath::hullplot(mk(3), "x", "y", "g", confidence_ellipses = TRUE)$notices$content),
                 "no data ellipse", fixed = TRUE)
    expect_false(grepl("no data ellipse",
                       val_strip_html(ClinicoPath::hullplot(mk(4), "x", "y", "g", confidence_ellipses = TRUE)$notices$content), fixed = TRUE))
    expect_match(val_strip_html(ClinicoPath::hullplot(mk(4), "x", "y", "g", outlier_detection = TRUE)$outliers$content),
                 "A: n too small", fixed = TRUE)
    expect_false(grepl("A: n too small",
                       val_strip_html(ClinicoPath::hullplot(mk(5), "x", "y", "g", outlier_detection = TRUE)$outliers$content), fixed = TRUE))
})

test_that("C10: jamovi fresh-instance redraw under requiresData = TRUE succeeds", {
    # Oracle: jamovi data-driven Image redraw contract (requiresData = TRUE, compact state)
    opts <- ClinicoPath:::hullplotOptions$new(
        x_var = "Sepal.Length", y_var = "Petal.Length", group_var = "Species", confidence_ellipses = TRUE
    )
    a1 <- ClinicoPath:::hullplotClass$new(options = opts, data = datasets::iris)
    a1$init(); a1$.__enclos_env__$private$.run()
    st <- a1$results$plot$state
    expect_true(isTRUE(st$ready))

    a2 <- ClinicoPath:::hullplotClass$new(options = opts, data = datasets::iris)
    a2$init()
    a2$results$plot$setState(st)
    f <- tempfile(fileext = ".png")
    grDevices::png(f, 800, 600)
    on.exit(try(grDevices::dev.off(), silent = TRUE), add = TRUE)
    expect_true(a2$.__enclos_env__$private$.plot(a2$results$plot, ggtheme = ggplot2::theme_bw(), theme = NULL))
})

test_that("C13: cross-output N consistency with missing values on bundled hullplot_clinical", {
    # Oracle: internal consistency across statistics, interpretation, summary, notices
    d <- ClinicoPath::hullplot_clinical
    d$tumor_volume[1:7] <- NA
    res <- ClinicoPath::hullplot(
        data = d, x_var = "tumor_volume", y_var = "ki67_index", group_var = "treatment_arm",
        show_statistics = TRUE, show_summary = TRUE
    )
    n_expected <- sum(stats::complete.cases(d[c("tumor_volume", "ki67_index", "treatment_arm")]))
    expect_true(isTRUE(res$plot$state$ready))
    expect_equal(sum(res$statistics$asDF$n), n_expected)
    expect_match(val_strip_html(res$interpretation$content), sprintf("Observations: %d data points", n_expected), fixed = TRUE)
    expect_match(val_strip_html(res$summary$content), sprintf("across %d observations", n_expected), fixed = TRUE)
    expect_match(val_strip_html(res$notices$content), sprintf("%d rows were plotted", n_expected), fixed = TRUE)
})

# --- Live regression tests for fixed validation defects ---

test_that("C09: VAL-hullplot-01 factor-with-values x_var unwraps numeric values via jmvcore::toNumeric()", {
    # Oracle: exact arithmetic on values attribute c(10..50) -> mean 30, c(110..150) -> mean 130
    f_val <- factor(c(10, 20, 30, 40, 50, 110, 120, 130, 140, 150))
    attr(f_val, "values") <- as.integer(levels(f_val))
    d <- data.frame(x = f_val, y = c(1:5, 11:15), g = factor(rep(c("A", "B"), each = 5)))
    res <- ClinicoPath::hullplot(
        data = d, x_var = "x", y_var = "y", group_var = "g",
        show_statistics = TRUE, outlier_detection = TRUE, show_summary = TRUE
    )
    st <- res$statistics$asDF
    expect_equal(st$x_mean, c(30, 130), tolerance = 1e-8)
    expect_true(isTRUE(res$plot$state$ready))
})

test_that("C09: VAL-hullplot-02 explicit NA factor level is excluded rather than plotted as group 'NA'", {
    # Oracle: only non-NA groups A and B should remain (2 groups, 16 rows)
    set.seed(1)
    d <- data.frame(
        x = c(rnorm(8, 0), rnorm(8, 5), 100, 101, 102),
        y = c(rnorm(8, 0), rnorm(8, 5), 100, 101, 102),
        g = factor(c(rep("A", 8), rep("B", 8), NA, NA, NA), exclude = NULL)
    )
    res <- ClinicoPath::hullplot(data = d, x_var = "x", y_var = "y", group_var = "g", show_statistics = TRUE)
    st <- res$statistics$asDF
    expect_equal(nrow(st), 2L)
    expect_equal(st$group, c("A", "B"))
})

test_that("C12: VAL-hullplot-03 clinical palette returns distinct colors for > 6 groups and jamovi palette works", {
    # Oracle: 7 and 11 distinct groups require 7 and 11 unique colors
    d <- data.frame(x = 1:21, y = 1:21, g = factor(rep(paste0("G", 1:7), each = 3)))
    opts <- ClinicoPath:::hullplotOptions$new(x_var = "x", y_var = "y", group_var = "g", color_palette = "clinical")
    a <- ClinicoPath:::hullplotClass$new(options = opts, data = d)
    expect_equal(length(unique(a$.__enclos_env__$private$.get_color_palette(7))), 7L)
    expect_equal(length(unique(a$.__enclos_env__$private$.get_color_palette(11))), 11L)

    opts_j <- ClinicoPath:::hullplotOptions$new(x_var = "x", y_var = "y", group_var = "g", color_palette = "jamovi")
    a_j <- ClinicoPath:::hullplotClass$new(options = opts_j, data = d)
    expect_equal(length(unique(a_j$.__enclos_env__$private$.get_color_palette(4))), 4L)

    opts_t <- ClinicoPath:::hullplotOptions$new(x_var = "x", y_var = "y", group_var = "g", plot_theme = "jamovi")
    a_t <- ClinicoPath:::hullplotClass$new(options = opts_t, data = d)
    expect_identical(a_t$.__enclos_env__$private$.get_plot_theme(ggplot2::theme_bw()), ggplot2::theme_bw())
})

test_that("C06: VAL-hullplot-04 overlapping groups copy-ready text does not claim 'revealed N distinct groups'", {
    # Oracle: narrative consistency audit
    d <- data.frame(x = c(-1, 1, -1, 1), y = c(-1, 1, -1, 1), g = factor(c("A", "A", "B", "B")))
    sm <- val_strip_html(ClinicoPath::hullplot(d, "x", "y", "g", show_summary = TRUE)$summary$content)
    expect_false(grepl("revealed 2 distinct groups", sm, fixed = TRUE))
    expect_match(sm, "visualized 2 groups defined by g", fixed = TRUE)
    expect_match(sm, "index = 0.00", fixed = TRUE)
})

test_that("C06: VAL-hullplot-05 constant-axis summary avoids ungrammatical 'described as unable to calculate'", {
    # Oracle: narrative audit
    d <- data.frame(x = c(rep(10, 6), rep(20, 6)), y = c(1:6, 1:6), g = factor(rep(c("A", "B"), each = 6)))
    sm <- val_strip_html(ClinicoPath::hullplot(d, "x", "y", "g", show_summary = TRUE)$summary$content)
    expect_false(grepl("described as unable to calculate", sm, fixed = TRUE))
    expect_match(sm, "could not be calculated", fixed = TRUE)
})

test_that("C02: VAL-hullplot-06 small-scale variables (1e-12) do not collapse to '0 +/- 0'", {
    # Oracle: nonzero positive values scaled by 1e-12 have nonzero means
    d <- data.frame(
        x = c(1, 2, 3, 4, 5, 11, 12, 13, 14, 15) * 1e-12,
        y = c(2, 3, 4, 5, 6, 12, 13, 14, 15, 16) * 1e-12,
        g = factor(rep(c("A", "B"), each = 5))
    )
    res <- ClinicoPath::hullplot(data = d, x_var = "x", y_var = "y", group_var = "g", show_statistics = TRUE)
    st <- res$statistics$asDF
    expect_true(all(st$x_mean > 0))
    expect_equal(st$x_mean, c(3e-12, 1.3e-11), tolerance = 1e-8)
})

test_that("C09: synthetic color_/size_ column prefixes do not overwrite axis columns", {
    # Security audit #1: column literally named "color_score" must not be overwritten when color_var = "score"
    d <- data.frame(
        color_score = c(10, 20, 30, 40, 50, 110, 120, 130, 140, 150),
        size_wt     = c(1:5, 11:15),
        g           = factor(rep(c("A", "B"), each = 5)),
        score       = factor(rep(c("Low", "High"), length.out = 10)),
        wt          = seq(1, 10)
    )
    res <- ClinicoPath::hullplot(
        data = d, x_var = "color_score", y_var = "size_wt", group_var = "g",
        color_var = "score", size_var = "wt", show_statistics = TRUE
    )
    expect_equal(res$statistics$asDF$x_mean, c(30, 130), tolerance = 1e-8)
    expect_equal(res$statistics$asDF$y_mean, c(3, 13), tolerance = 1e-8)
    f <- tempfile(fileext = ".png")
    expect_no_error(res$plot$saveAs(f))
})
